package com.bank.grpcweb;

import com.bank.grpcweb.gen.*;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

// Pure gRPC server — unaware that a browser is calling via Envoy translation.
public class BalanceServiceImpl extends BalanceServiceGrpc.BalanceServiceImplBase {
    private static final Logger log = Logger.getLogger(BalanceServiceImpl.class.getName());
    private final Map<String, String> holders = Map.of("SAV2001", "Rajesh", "CUR3001", "Priya");
    private final Map<String, BigDecimal> balances = Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000"));    // Priya

    @Override
    public void getBalance(BalanceRequest req, StreamObserver<BalanceResponse> obs) {
        log.info(() -> "gRPC-Web GetBalance for " + req.getAccountId());
        BigDecimal bal = balances.get(req.getAccountId());
        if (bal == null) {
            obs.onError(io.grpc.Status.NOT_FOUND
                .withDescription("account not found").asRuntimeException());
            return;
        }
        obs.onNext(BalanceResponse.newBuilder()
            .setAccountId(req.getAccountId())
            .setHolder(holders.get(req.getAccountId()))
            .setBalance(bal.toString())
            .build());
        obs.onCompleted();
    }
}
