package com.bank.grpcweb;

import io.grpc.Server;
import io.grpc.ServerBuilder;
import java.util.logging.Logger;

public class GrpcServer {
    private static final Logger log = Logger.getLogger(GrpcServer.class.getName());

    public static void main(String[] args) throws Exception {
        Server server = ServerBuilder.forPort(9090)      // Envoy forwards here over HTTP/2
            .addService(new BalanceServiceImpl())
            .build().start();
        log.info("Pure gRPC BalanceService on 9090 (Envoy on 8080 for browsers)");
        server.awaitTermination();
    }
}
