package com.bank.grpcweb;

import com.bank.grpcweb.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.logging.Logger;

// Represents the NATIVE gRPC call that lands on the backend AFTER Envoy translates
// the browser's gRPC-Web request. The browser would use a generated grpc-web JS stub.
public class BalanceClient {
    private static final Logger log = Logger.getLogger(BalanceClient.class.getName());

    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        BalanceServiceGrpc.BalanceServiceBlockingStub stub =
            BalanceServiceGrpc.newBlockingStub(channel);
        BalanceResponse resp = stub.getBalance(
            BalanceRequest.newBuilder().setAccountId("SAV2001").build());
        log.info(() -> "Holder=" + resp.getHolder() + " Balance=Rs." + resp.getBalance());
        channel.shutdown();
    }
}
